/**
 * C4 - AI mentor matching: multi-criteria, capacity-aware, explainable.
 *
 * TypeScript mirror of `ml/c4/src/mentor-matching/matcher.py`. The criteria formulas and
 * the AHP weights (from `model/matching-model.json`, generated by
 * `python ml/c4/run_pipeline.py`; never edit it by hand) are the same on both sides, and
 * `tests/unit/c4/c4-parity.test.ts` checks that the scores agree.
 *
 * SYNTHETIC DATA: the weights are provisional AHP judgements and the evaluation uses
 * simulated expert labels, so results validate the pipeline, not real-world accuracy.
 */
import mentorsJson from "./model/demo-mentors.json";
import modelJson from "./model/matching-model.json";

export type CriterionId = "skill" | "interest" | "language" | "availability" | "capacity";
export type TaxonomyItem = { id: string; label: string };

export type MatchingModel = {
  version: string;
  warning: string;
  criteria: CriterionId[];
  weights: Record<CriterionId, number>;
  consistencyRatio: number;
  maxSkillLevel: number;
  taxonomy: { skills: TaxonomyItem[]; interests: TaxonomyItem[]; languages: TaxonomyItem[]; slots: TaxonomyItem[] };
  results: {
    ndcgBaselineCapacityFiltered: number;
    ndcgProposed: number;
    overloadBaseline: number;
    overloadProposed: number;
    giniBaseline: number;
    giniProposed: number;
    intake: number;
  };
};

export type MentorProfile = {
  id: string;
  name: string;
  headline: string;
  expertise: Record<string, number>;
  interests: string[];
  languages: string[];
  slots: string[];
  capacity: number;
  load: number;
};

export type StudentNeeds = {
  /** skill id -> how much help is wanted (1 = a little, 3 = a lot) */
  needs: Record<string, number>;
  interests: string[];
  preferredLanguage: string;
  languages: string[];
  slots: string[];
};

export type Criteria = Record<CriterionId, number>;

export type MentorMatch = {
  mentor: MentorProfile;
  score: number;
  criteria: Criteria;
  reasons: string[];
};

export const matchingModel = modelJson as MatchingModel;
export const demoMentors = mentorsJson as unknown as MentorProfile[];
export const isSyntheticModel = matchingModel.version.endsWith("-synthetic");

const label = (items: TaxonomyItem[], id: string) => items.find((i) => i.id === id)?.label ?? id;

export function criteriaFor(student: StudentNeeds, mentor: MentorProfile): Criteria {
  const max = matchingModel.maxSkillLevel;
  const needEntries = Object.entries(student.needs);
  const needTotal = needEntries.reduce((sum, [, level]) => sum + level, 0);
  let skill = 0;
  if (needTotal) {
    let covered = 0;
    for (const [skillId, level] of needEntries) covered += (level * Math.min(mentor.expertise[skillId] ?? 0, max)) / max;
    skill = covered / needTotal;
  }

  const a = new Set(student.interests);
  const b = new Set(mentor.interests);
  const union = new Set([...a, ...b]);
  const shared = [...a].filter((x) => b.has(x)).length;
  const interest = union.size ? shared / union.size : 0;

  let language = 0;
  if (mentor.languages.includes(student.preferredLanguage)) language = 1;
  else if (student.languages.some((l) => mentor.languages.includes(l))) language = 0.5;

  const studentSlots = new Set(student.slots);
  const availability = studentSlots.size ? mentor.slots.filter((s) => studentSlots.has(s)).length / studentSlots.size : 0;
  const capacity = mentor.capacity ? Math.max(mentor.capacity - mentor.load, 0) / mentor.capacity : 0;

  return { skill, interest, language, availability, capacity };
}

export function scoreFor(c: Criteria): number {
  let score = 0;
  for (const name of matchingModel.criteria) score += matchingModel.weights[name] * c[name];
  return score;
}

/** Human-readable reasons for one match (the explainable part shown to the student). */
export function reasonsFor(student: StudentNeeds, mentor: MentorProfile, c: Criteria): string[] {
  const { skills, interests, languages, slots } = matchingModel.taxonomy;
  const reasons: string[] = [];
  const strong = Object.keys(student.needs).filter((s) => (mentor.expertise[s] ?? 0) >= 2);
  if (strong.length) reasons.push(`Experienced in ${strong.map((s) => label(skills, s)).join(", ")}`);
  else if (c.skill > 0) reasons.push("Some experience in the skills you asked about");
  const sharedInterests = student.interests.filter((i) => mentor.interests.includes(i));
  if (sharedInterests.length) reasons.push(`Shares your interest in ${sharedInterests.map((i) => label(interests, i)).join(", ")}`);
  if (c.language === 1) reasons.push(`Mentors in ${label(languages, student.preferredLanguage)}`);
  else if (c.language === 0.5) {
    const common = student.languages.find((l) => mentor.languages.includes(l));
    if (common) reasons.push(`Can mentor in ${label(languages, common)}`);
  }
  const sharedSlots = student.slots.filter((s) => mentor.slots.includes(s));
  if (sharedSlots.length) reasons.push(`Free on ${sharedSlots.map((s) => label(slots, s)).join(", ")}`);
  const free = Math.max(mentor.capacity - mentor.load, 0);
  reasons.push(`${free} of ${mentor.capacity} mentee places free`);
  return reasons;
}

/** Mentors with free capacity, best first. A full mentor is never recommended. */
export function rankMentors(student: StudentNeeds, mentors: MentorProfile[] = demoMentors): MentorMatch[] {
  return mentors
    .filter((m) => m.load < m.capacity)
    .map((mentor) => {
      const criteria = criteriaFor(student, mentor);
      return { mentor, score: scoreFor(criteria), criteria, reasons: reasonsFor(student, mentor, criteria) };
    })
    .sort((x, y) => y.score - x.score || (x.mentor.id < y.mentor.id ? -1 : x.mentor.id > y.mentor.id ? 1 : 0));
}
